-- ═══════════════════════════════════════════════════════════════════════════
-- RÉGLAGE — LES FICHES DE PROCÉDURE (2026-11-25)
--
-- La fiche du Rituel Sowa, decidee sur la notice de Pouxit XF et les recommandations de la Societe francaise de dermatologie, part VALIDEE (« Decide et valide la fiche Sowa », Yeman). Les deux prestations offertes du rituel sont creees (« cree, offertes, les prestations du catalogue qui manquent ») : le controle a J+7 et la Couronne Cocon, a 0 F, avec leur fiche en brouillon.
--
-- Écrit par `node scripts/fiches-de-procedure/reglage.mjs` depuis les fiches
-- de `scripts/fiches-de-procedure/familles/`. Ne pas le corriger à la main :
-- corriger la famille, puis le refaire.
--
-- 3 fiche(s) : 1 validée(s) (version 1, signée
-- « la direction (décision confiée à Claude le 25 novembre 2026) »), 2 en brouillon.
-- 2 prestations offertes créées (0 F) et retirées du site et de Ma Couronne.
--
-- GARDES : une fiche déjà validée, ou dont le brouillon a été corrigé par la
-- direction, n'est pas touchée ; une prestation déjà là ou retirée par la
-- Maison ne se repose pas. Un repli d'abord. Rejouable sans rien changer de plus.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── Le repli ──────────────────────────────────────────────────────────
create table if not exists public.repli_documents_20261125_fiches_de_procedure as
  select * from public.documents where key in ('mnd_fiches_de_procedure', 'mnd_vitrine_config');
alter table public.repli_documents_20261125_fiches_de_procedure enable row level security;

-- ── ① Les prestations offertes ─────────────────────────────────────────
insert into public.catalog_services (id, branch_id, data)
select v.id, null, v.data
  from (values
    ('sv-sowa-controle', $fiches${"id":"sv-sowa-controle","categoryId":"cat-soins","name":"Sówà™ · Le Contrôle à J+7","description":"Sówà™ : le contrôle à J+7.\nSept jours après votre Rituel Sówà™, nous regardons de nouveau votre cuir chevelu et vos locks, et nous faisons la seconde application, pour nous assurer que tout est bien fini.\n\nVous en retirez : la certitude que le rituel a fait son œuvre.\n\nOffert avec le Rituel Sówà™.","palier":"Fondation","priceXof":0,"hidePrice":false,"priceMode":"fixe","sessions":1,"master":"Team","durationMin":45,"order":10001,"fenetreApresVenue":{"deSemaines":1,"aSemaines":2}}$fiches$::jsonb),
    ('sv-kids-couronne-cocon', $fiches${"id":"sv-kids-couronne-cocon","categoryId":"cat-mnd-kids","name":"Couronne Cocon · la coiffure protectrice","description":"La coiffure protectrice des petites têtes après un Rituel Sówà™ : les locks rassemblées et attachées près de la tête, sans tension. Offerte aux enfants avec le Rituel Sówà™.","palier":"Fondation","priceXof":0,"hidePrice":false,"priceMode":"fixe","sessions":1,"master":"Team","durationMin":20,"order":100,"reserveEnfants":true}$fiches$::jsonb)
  ) as v(id, data)
 where not exists (select 1 from public.catalog_services s where s.id = v.id)
   and not exists (select 1 from public.catalog_tombstones t where t.id = v.id);

-- ── ② Elles ne se réservent pas seules : hors du site, hors de Ma Couronne ──
update public.documents d
   set data = jsonb_set(
         jsonb_set(
           d.data,
           '{siteMasques,services}',
           (d.data->'siteMasques'->'services')
             || coalesce((select jsonb_agg(x) from unnest(array['sv-sowa-controle', 'sv-kids-couronne-cocon']) as x
                           where not (d.data->'siteMasques'->'services') ? x), '[]'::jsonb)),
         '{hiddenServices}',
         (d.data->'hiddenServices')
           || coalesce((select jsonb_agg(x) from unnest(array['sv-sowa-controle', 'sv-kids-couronne-cocon']) as x
                         where not (d.data->'hiddenServices') ? x), '[]'::jsonb)),
       updated_at = now()
 where d.key = 'mnd_vitrine_config'
   and jsonb_typeof(d.data->'siteMasques'->'services') = 'array'
   and jsonb_typeof(d.data->'hiddenServices') = 'array'
   and not ((d.data->'siteMasques'->'services') ?& array['sv-sowa-controle', 'sv-kids-couronne-cocon']
        and (d.data->'hiddenServices') ?& array['sv-sowa-controle', 'sv-kids-couronne-cocon']);

-- ── ③ Les fiches ──────────────────────────────────────────────────────
with neuves as (select $fiches${"1740l5ysxj":{"serviceId":"1740l5ysxj","titre":"Rituel Sówà™ · Rituel anti-poux Maison MND","brouillon":{"objectif":[{"id":"ob-1","texte":"Éliminer les poux des locks, avec discrétion et sans jugement.","source":"catalogue"},{"id":"ob-2","texte":"À la sortie : un cuir chevelu traité, les lentes retirées au peigne fin.","source":"catalogue"},{"id":"ob-3","texte":"Le rituel tient en deux venues : le premier rendez-vous, puis le contrôle offert à J+7.","source":"maison"}],"public":[{"id":"pu-1","texte":"Toute personne qui a des démangeaisons, ou qui a vu des poux ou des lentes, chez elle ou chez un proche.","source":"catalogue"},{"id":"pu-2","texte":"À partir de 6 mois. Convient aux femmes enceintes ou qui allaitent.","source":"notice","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"pu-3","texte":"On ne l’applique pas : avant 6 mois, sur une peau lésée, en cas d’allergie à l’un de ses composants.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"pu-4","texte":"Pour un enfant (jusqu’à 15 ans, MND Kids), la coiffure protectrice Couronne Cocon est offerte.","source":"maison"}],"produits":[{"id":"pr-1","texte":"Pouxit XF, lotion en flacon : diméticone à 4 %, dispositif médical. Il agit par action physique, en recouvrant les poux et les lentes.","source":"notice","detail":"Pouxit XF lotion, flacon de 100 ou 200 ml","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"pr-2","texte":"Pouxit seul. Ni poudre de neem ni poudre de shikakaï dans le rituel : aucune institution ne les recommande contre les poux, et les études de sécurité et d’efficacité manquent.","source":"maison","ref":"Memorial Sloan Kettering Cancer Center, neem (mai 2025) · mskcc.org/cancer-care/integrative-medicine/herbs/neem"},{"id":"pr-3","texte":"La lotion en flacon, jamais un spray : les sprays sont contre-indiqués dès qu’il y a de l’asthme.","source":"pratique","ref":"Société française de dermatologie, note de novembre 2019 · sfdermato.org/media/pdf/actualite/note-pediculos-sfd-gridist-51283d08cd07c9ac26310a6d2669ff30.pdf"},{"id":"pr-4","texte":"Shampoing Doux Essentiel de la Maison, pour retirer le produit.","source":"maison","detail":"SH-ESS-P1"},{"id":"pr-5","texte":"Peigne fin, pour le retrait des lentes.","source":"catalogue"},{"id":"pr-6","texte":"Cape et serviettes du rituel, gants à usage unique.","source":"maison"}],"arrivee":[{"id":"ar-1","texte":"Le flacon en main est bien Pouxit XF, en lotion. Si c’est une autre référence (Flash, shampooing, spray), cette fiche ne vaut pas : on suit la notice de ce flacon et on prévient la direction.","source":"maison"},{"id":"ar-2","texte":"La notice de la boîte fait foi : si elle diffère de cette fiche, c’est elle qu’on suit, et on prévient la direction.","source":"maison"},{"id":"ar-3","texte":"Examiner le cuir chevelu avec la cliente, avec discrétion et sans jugement.","source":"catalogue"},{"id":"ar-4","texte":"Si l’examen ne montre ni pou vivant ni lente, on ne traite pas : on le dit à la cliente et on prévient la direction.","source":"maison","ref":"INRS, pédiculose du cuir chevelu (novembre 2024) · inrs.fr/dam/eficatt/FicheEficatt/EFICATT_Pédiculose-du-cuir-chevelu-1.pdf"},{"id":"ar-5","texte":"Âge : 6 mois révolus au moins.","source":"notice","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"ar-6","texte":"Cuir chevelu sans plaie ni lésion : le produit ne s’applique pas sur une peau lésée.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"ar-7","texte":"Lui demander si elle a déjà réagi à un produit anti-poux : pas d’application en cas d’allergie à l’un de ses composants.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"ar-8","texte":"Aucune flamme ni source de chaleur près d’elle tant que le produit est sur la tête : ni casque, ni sèche-cheveux, ni cigarette.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"}],"etapes":[{"id":"et-1","texte":"Examen du cuir chevelu, avec la cliente.","source":"catalogue"},{"id":"et-2","texte":"Protéger ses yeux et ses épaules. Essuyer tout de suite ce qui tombe au sol : le produit rend le sol glissant.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"et-3","texte":"Sur des locks et un cuir chevelu secs, appliquer Pouxit XF lock par lock, jusqu’à tout recouvrir, cuir chevelu compris.","source":"notice","detail":"Assez pour tout recouvrir : la notice ne donne pas de dose","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"et-4","texte":"Laisser agir.","source":"notice","detail":"15 minutes","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"et-5","texte":"Sans mouiller avant, appliquer le shampoing directement sur les locks, faire mousser, puis rincer.","source":"notice","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"et-6","texte":"Refaire un shampoing si les locks restent grasses, puis rincer jusqu’à ce que l’eau soit claire.","source":"pratique"},{"id":"et-7","texte":"Retrait des lentes au peigne fin.","source":"catalogue"},{"id":"et-8","texte":"Le peigne ne traverse pas une lock : le passer aux racines et sur les cheveux libres, sans défaire les locks.","source":"pratique","ref":"Université de Californie, UC IPM (juillet 2020) · ipm.ucanr.edu/PMG/PESTNOTES/pn7446.html"},{"id":"et-9","texte":"Une fois le produit entièrement retiré, sécher complètement, jusqu’au cœur des locks.","source":"pratique"},{"id":"et-10","texte":"Pour un enfant : la Couronne Cocon, offerte. Voir sa fiche.","source":"maison"},{"id":"et-11","texte":"Poser avec elle le contrôle, offert, à J+7 : la prestation « Sówà™ · Le Contrôle à J+7 ».","source":"maison"},{"id":"et-12","texte":"Recommander le soin hydratant DÀNDÀN™, à poser après le contrôle.","source":"maison"},{"id":"et-13","texte":"Après elle : cape et serviettes lavées à 60 °C, peigne fin lavé puis mis de côté 3 jours.","source":"maison","ref":"INRS, pédiculose du cuir chevelu (novembre 2024) · inrs.fr/dam/eficatt/FicheEficatt/EFICATT_Pédiculose-du-cuir-chevelu-1.pdf"}],"conseils":[{"id":"co-1","texte":"Revenir à J+7 pour le contrôle, offert : la seconde application s’y fait.","source":"maison"},{"id":"co-2","texte":"Draps, taies, bonnets, foulards et serviettes : lavés à 60 °C, ou enfermés 10 jours dans un sac.","source":"pratique","ref":"Société française de dermatologie, page mise à jour le 15 mars 2026 · dermato-info.fr/traiter-les-poux-de-tete"},{"id":"co-3","texte":"Peignes et brosses : lavés, puis mis de côté 3 jours.","source":"pratique","ref":"INRS, pédiculose du cuir chevelu (novembre 2024) · inrs.fr/dam/eficatt/FicheEficatt/EFICATT_Pédiculose-du-cuir-chevelu-1.pdf"},{"id":"co-4","texte":"Regarder les têtes de toute la maison. Seules celles qui portent des poux vivants se traitent.","source":"pratique","ref":"INRS, pédiculose du cuir chevelu (novembre 2024) · inrs.fr/dam/eficatt/FicheEficatt/EFICATT_Pédiculose-du-cuir-chevelu-1.pdf"},{"id":"co-5","texte":"Prévenir l’école ou la garderie, pour que les autres têtes soient regardées.","source":"pratique","ref":"Conseil supérieur d’hygiène publique de France (2003) · hcsp.fr/explore.cgi/a_mt_270603_pediculose.pdf"},{"id":"co-6","texte":"Le soin hydratant DÀNDÀN™ est recommandé à la suite du rituel, après le contrôle.","source":"maison"}],"suivi":[{"id":"su-1","texte":"Compris : le premier rendez-vous, le Rituel Sówà™.","source":"maison"},{"id":"su-2","texte":"Offert : le contrôle à J+7, où se fait la seconde application.","source":"maison","ref":"Société française de dermatologie, page mise à jour le 15 mars 2026 · dermato-info.fr/traiter-les-poux-de-tete"},{"id":"su-3","texte":"Offert aux enfants : la coiffure protectrice Couronne Cocon.","source":"maison"},{"id":"su-4","texte":"Recommandé : le soin hydratant DÀNDÀN™, au prix du catalogue.","source":"maison"},{"id":"su-5","texte":"Le Rituel Sówà™ ne porte aucune remise.","source":"catalogue"},{"id":"su-6","texte":"Durée au catalogue : 1 h.","source":"catalogue"},{"id":"su-7","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]},"brouillonLe":"2026-11-25T09:20:05.476Z","brouillonPar":"Recherche du 25 novembre 2026","validee":{"numero":1,"le":"2026-11-25T09:20:05.476Z","par":"la direction (décision confiée à Claude le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Éliminer les poux des locks, avec discrétion et sans jugement.","source":"catalogue"},{"id":"ob-2","texte":"À la sortie : un cuir chevelu traité, les lentes retirées au peigne fin.","source":"catalogue"},{"id":"ob-3","texte":"Le rituel tient en deux venues : le premier rendez-vous, puis le contrôle offert à J+7.","source":"maison"}],"public":[{"id":"pu-1","texte":"Toute personne qui a des démangeaisons, ou qui a vu des poux ou des lentes, chez elle ou chez un proche.","source":"catalogue"},{"id":"pu-2","texte":"À partir de 6 mois. Convient aux femmes enceintes ou qui allaitent.","source":"notice","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"pu-3","texte":"On ne l’applique pas : avant 6 mois, sur une peau lésée, en cas d’allergie à l’un de ses composants.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"pu-4","texte":"Pour un enfant (jusqu’à 15 ans, MND Kids), la coiffure protectrice Couronne Cocon est offerte.","source":"maison"}],"produits":[{"id":"pr-1","texte":"Pouxit XF, lotion 