maison"}],"produits":[{"id":"pr-1","texte":"Pouxit XF, lotion en flacon : diméticone à 4 %, dispositif médical. Il agit par action physique, en recouvrant les poux et les lentes.","source":"notice","detail":"Pouxit XF lotion, flacon de 100 ou 200 ml","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"pr-2","texte":"Shampoing Doux Essentiel de la Maison, peigne fin, cape et serviettes du rituel, gants à usage unique.","source":"maison","detail":"SH-ESS-P1"}],"arrivee":[{"id":"ar-1","texte":"Relire sur sa fiche la date du rituel : le contrôle se fait de 7 à 10 jours après.","source":"maison","ref":"Société française de dermatologie, page mise à jour le 15 mars 2026 · dermato-info.fr/traiter-les-poux-de-tete"},{"id":"ar-2","texte":"Lui demander ce qu’elle a vu depuis, et si son cuir chevelu a réagi au produit. S’il a rougi ou brûlé : pas de seconde application, on prévient la direction et on lui conseille de consulter.","source":"pratique"},{"id":"ar-3","texte":"Examiner le cuir chevelu avec elle, avec discrétion et sans jugement.","source":"catalogue"},{"id":"ar-4","texte":"Le flacon en main est bien Pouxit XF, en lotion. Si c’est une autre référence (Flash, shampooing, spray), cette fiche ne vaut pas : on suit la notice de ce flacon et on prévient la direction.","source":"maison"},{"id":"ar-5","texte":"La notice de la boîte fait foi : si elle diffère de cette fiche, c’est elle qu’on suit, et on prévient la direction.","source":"maison"},{"id":"ar-6","texte":"Âge : 6 mois révolus au moins.","source":"notice","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"ar-7","texte":"Cuir chevelu sans plaie ni lésion : le produit ne s’applique pas sur une peau lésée.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"ar-8","texte":"Lui demander si elle a déjà réagi à un produit anti-poux : pas d’application en cas d’allergie à l’un de ses composants.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"ar-9","texte":"Aucune flamme ni source de chaleur près d’elle tant que le produit est sur la tête : ni casque, ni sèche-cheveux, ni cigarette.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"}],"etapes":[{"id":"et-1","texte":"Examen du cuir chevelu : poux vivants, lentes.","source":"catalogue"},{"id":"et-2","texte":"Protéger ses yeux et ses épaules. Essuyer tout de suite ce qui tombe au sol : le produit rend le sol glissant.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"et-3","texte":"Sur des locks et un cuir chevelu secs, appliquer Pouxit XF lock par lock, jusqu’à tout recouvrir, cuir chevelu compris.","source":"notice","detail":"Assez pour tout recouvrir : la notice ne donne pas de dose","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"et-4","texte":"Laisser agir.","source":"notice","detail":"15 minutes","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"et-5","texte":"Sans mouiller avant, appliquer le shampoing directement sur les locks, faire mousser, puis rincer.","source":"notice","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"et-6","texte":"Refaire un shampoing si les locks restent grasses, puis rincer jusqu’à ce que l’eau soit claire.","source":"pratique"},{"id":"et-7","texte":"Retrait des lentes au peigne fin.","source":"catalogue"},{"id":"et-8","texte":"Le peigne ne traverse pas une lock : le passer aux racines et sur les cheveux libres, sans défaire les locks.","source":"pratique","ref":"Université de Californie, UC IPM (juillet 2020) · ipm.ucanr.edu/PMG/PESTNOTES/pn7446.html"},{"id":"et-9","texte":"Une fois le produit entièrement retiré, sécher complètement, jusqu’au cœur des locks.","source":"pratique"},{"id":"et-10","texte":"Après elle : cape et serviettes lavées à 60 °C, peigne fin lavé puis mis de côté 3 jours.","source":"maison","ref":"INRS, pédiculose du cuir chevelu (novembre 2024) · inrs.fr/dam/eficatt/FicheEficatt/EFICATT_Pédiculose-du-cuir-chevelu-1.pdf"}],"conseils":[{"id":"co-1","texte":"Regarder de nouveau la tête cinq jours plus tard, à J+12. S’il reste des poux vivants, revenir nous voir ou consulter.","source":"pratique","ref":"Société française de dermatologie, page mise à jour le 15 mars 2026 · dermato-info.fr/traiter-les-poux-de-tete"},{"id":"co-2","texte":"Draps, taies, bonnets, foulards et serviettes : lavés à 60 °C, ou enfermés 10 jours dans un sac.","source":"pratique","ref":"Société française de dermatologie, page mise à jour le 15 mars 2026 · dermato-info.fr/traiter-les-poux-de-tete"},{"id":"co-3","texte":"Peignes et brosses : lavés, puis mis de côté 3 jours.","source":"pratique","ref":"INRS, pédiculose du cuir chevelu (novembre 2024) · inrs.fr/dam/eficatt/FicheEficatt/EFICATT_Pédiculose-du-cuir-chevelu-1.pdf"},{"id":"co-4","texte":"Regarder les têtes de toute la maison. Seules celles qui portent des poux vivants se traitent.","source":"pratique","ref":"INRS, pédiculose du cuir chevelu (novembre 2024) · inrs.fr/dam/eficatt/FicheEficatt/EFICATT_Pédiculose-du-cuir-chevelu-1.pdf"},{"id":"co-5","texte":"Prévenir l’école ou la garderie, pour que les autres têtes soient regardées.","source":"pratique","ref":"Conseil supérieur d’hygiène publique de France (2003) · hcsp.fr/explore.cgi/a_mt_270603_pediculose.pdf"},{"id":"co-6","texte":"Le soin hydratant DÀNDÀN™ peut maintenant se poser.","source":"maison"}],"suivi":[{"id":"su-1","texte":"Offert : il fait partie du Rituel Sówà™.","source":"maison"},{"id":"su-2","texte":"Durée au catalogue : 45 min. Il se pose de 1 à 2 semaines après la dernière venue ; le Trône avertit en dehors.","source":"catalogue"},{"id":"su-3","texte":"Si des poux vivants sont encore là au contrôle : prévenir la direction, qui décide de la suite. Pour des cheveux qu’on ne peut pas peigner, l’Université de Californie décrit trois applications espacées de 5 à 6 jours.","source":"maison","ref":"Université de Californie, UC IPM (juillet 2020) · ipm.ucanr.edu/PMG/PESTNOTES/pn7446.html"},{"id":"su-4","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]},"brouillonLe":"2026-11-25T09:20:05.476Z","brouillonPar":"Recherche du 25 novembre 2026"},"sv-kids-couronne-cocon":{"serviceId":"sv-kids-couronne-cocon","titre":"Couronne Cocon · la coiffure protectrice","brouillon":{"objectif":[{"id":"ob-1","texte":"La coiffure protectrice des enfants après un Rituel Sówà™ : les locks rassemblées et attachées près de la tête, sans tension. Offerte.","source":"maison","aValider":"La forme exacte de la Couronne Cocon (chignon, couronne de locks, foulard) n’est écrite nulle part : à décrire par la Maison, photo à l’appui. C’est le seul point que la recherche ne peut pas trancher."}],"public":[{"id":"pu-1","texte":"Les enfants (jusqu’à 15 ans, MND Kids) qui viennent de faire leur Rituel Sówà™.","source":"maison"}],"produits":[{"id":"pr-1","texte":"Élastiques gainés, qui n’accrochent pas le cheveu.","source":"pratique","ref":"American Academy of Dermatology, cheveux de l’enfant · aad.org/public/parents-kids/healthy-habits/parents/hair-care-habits"}],"arrivee":[{"id":"ar-1","texte":"Les locks sont complètement sèches, et le produit du rituel entièrement retiré.","source":"pratique"},{"id":"ar-2","texte":"Regarder le contour : sur un contour dégarni ou des racines fines, on rassemble sans attacher serré.","source":"pratique","ref":"Dr Kenner-Bell, dermatologue pédiatrique, dans Dermatology Times · dermatologytimes.com/view/teaching-kids-to-love-their-hair-comprehensive-strategies-for-curly-and-coily-hair-care"}],"etapes":[{"id":"et-1","texte":"Rassembler les locks près de la tête.","source":"maison"},{"id":"et-2","texte":"Attacher sans serrer : chez l’enfant, pas de chignon serré.","source":"pratique","ref":"Dr Kenner-Bell, dermatologue pédiatrique, dans Dermatology Times · dermatologytimes.com/view/teaching-kids-to-love-their-hair-comprehensive-strategies-for-curly-and-coily-hair-care"},{"id":"et-3","texte":"Aucune tension à la racine : si la cliente dit que ça tire, on desserre tout de suite.","source":"pratique"},{"id":"et-4","texte":"Faire bouger la tête à l’enfant : rien ne doit tirer ni glisser.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"La garder jusqu’au contrôle de J+7 si elle reste confortable.","source":"maison"},{"id":"co-2","texte":"Si elle tire, fait mal ou donne des petits boutons au contour : la défaire.","source":"pratique","ref":"American Academy of Dermatology, coiffures qui tirent · aad.org/public/diseases/hair-loss/causes/hairstyles"}],"suivi":[{"id":"su-1","texte":"Offerte aux enfants avec le Rituel Sówà™.","source":"maison"},{"id":"su-2","texte":"Durée au catalogue : 20 min.","source":"catalogue"},{"id":"su-3","texte":"Réservée aux enfants (MND Kids). Elle ne se réserve pas en ligne : c’est l’équipe qui la pose.","source":"catalogue"}]},"brouillonLe":"2026-11-25T09:20:05.476Z","brouillonPar":"Recherche du 25 novembre 2026"}}$fiches$::jsonb as j)
update public.documents d
   set data = (
         select coalesce(jsonb_object_agg(t.k, t.v), '{}'::jsonb)
           from (
             select n.key as k,
                    case
                      when d.data ? n.key and (
                             (d.data->n.key) ? 'validee'
                          or coalesce(d.data->n.key->>'brouillonPar', '') not in ('', 'Recherche du 25 novembre 2026')
                           ) then d.data->n.key
                      else n.value
                    end as v
               from neuves, jsonb_each(neuves.j) as n
             union all
             select e.key, e.value
               from neuves, jsonb_each(d.data) as e
              where not (neuves.j ? e.key)
           ) t),
       updated_at = now()
 where d.key = 'mnd_fiches_de_procedure'
   and jsonb_typeof(d.data) = 'object';

