with neuves as (select $fiches${"1740l5ysxj":{"serviceId":"1740l5ysxj","titre":"Rituel Sówà™ · Rituel anti-poux Maison MND","brouillon":{"objectif":[{"id":"ob-1","texte":"Éliminer les poux des locks, avec discrétion et sans jugement.","source":"catalogue"},{"id":"ob-2","texte":"À la sortie : un cuir chevelu traité, les lentes retirées au peigne fin.","source":"catalogue"},{"id":"ob-3","texte":"Le rituel tient en deux venues : le premier rendez-vous, puis le contrôle offert à J+7.","source":"maison"}],"public":[{"id":"pu-1","texte":"Toute personne qui a des démangeaisons, ou qui a vu des poux ou des lentes, chez elle ou chez un proche.","source":"catalogue"},{"id":"pu-2","texte":"À partir de 6 mois. Convient aux femmes enceintes ou qui allaitent.","source":"notice","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"pu-3","texte":"On ne l’applique pas : avant 6 mois, sur une peau lésée, en cas d’allergie à l’un de ses composants.","source":"notice","ref":"Notice de Pouxit XF reproduite par une pharmacie · atida.fr/pouxit-extra-fort-lotion-anti-poux-100ml.html"},{"id":"pu-4","texte":"Pour un enfant (jusqu’à 15 ans, MND Kids), la coiffure protectrice Couronne Cocon est offerte.","source":"maison"}],"produits":[{"id":"pr-1","texte":"Pouxit XF, lotion en flacon : diméticone à 4 %, dispositif médical. Il agit par action physique, en recouvrant les poux et les lentes.","source":"notice","detail":"Pouxit XF lotion, flacon de 100 ou 200 ml","ref":"Fabricant, page Pouxit XF (juillet 2024) · pouxit.fr/product/pouxit-xf"},{"id":"pr-2","texte":"Pouxit seul. Ni poudre de neem ni poudre de shikakaï dans le rituel : aucune institution ne les recommande contre les poux, et les études de sécurité et d’efficacité manquent.","source":"maison","ref":"Memorial Sloan Kettering Cancer Center, neem (mai 2025) · mskcc.org/cancer-care/integrative-medicine/herbs/neem"},{"id":"pr-3","texte":"La lotion en flacon, jamais un spray : les sprays sont contre-indiqué